/** Each scope represents a `produce` call. */

export interface ImmerScope {
	patches_?: Patch[]
	inversePatches_?: Patch[]
	patchPlugin_?: PatchesPlugin
	mapSetPlugin_?: MapSetPlugin
	arrayMethodsPlugin_?: ArrayMethodsPlugin
	canAutoFreeze_: boolean
	drafts_: any[]
